// generated by tools/map_bond.py from src/bond/ragdoll.cpp
#define AUF_LANG_FRE
// Ragdolls (auf::ragdolls, off by default): a dead enemy goes limp and falls with its weight onto the ground it died
// on, in place of the game's death animation. Only the body's look: the game's death (its entity, its fall, its
// fade and removal) goes on underneath and nothing of its state is written.
//
// A character's skeletal model ([edict+0x10C]) keeps its bones' model-space pose at [m+0x5C]: 0x20 an entry, the
// position (x, y, z, w) then the rotation as a quaternion (x, y, z, w), [m+0x50] (ushort) of them, the parents at
// [m+0x54] (8 bytes a bone, the parent's index first, -1 the root). 0x146D60 (vtable +0x104, ecx the model) turns that
// pose into the skin matrices once a frame; the ragdoll's pose is written in for that call only and the game's put
// back after it (the game reads the pose itself for tags and drops). The bones are found by name: the mesh's [m+0x10]
// +0x74 holds 8 bytes a bone, the name's hash at +4, and 0x13EB50 keeps the hashes of the 34 names (HIP, RTHIGH ... ,
// at 0x2285A8) at 0x435220. The dead are the game's list of dead actors ([0x330400], [0x330404] of them; players are
// never in it).
// 17 joints become points that fall (Verlet; the motion they had the frame before carries on), hold their distances
// (the hips, chest, head, shoulders and hip joints as one piece, the limbs' bones) and stop at the floor the body died
// on (the lowest of its bones then, model space being upright), with friction. Each bone is then its kept pose moved
// as its joint moved: the torso's turned with the frame of its points, each limb bone aimed from its joint at the
// next, the rest (hands, fingers, toes, the weapon's tag) carried with their parents. A body that lies still (or
// after 8 s) sleeps: its last pose drawn as it is.
// AUF_RAGDOLL=0/1 overrides the setting; AUF_RAGDOLL_TEST=1 makes every character go limp after 2 s (to look at
// without a fight); AUF_RAGDOLL_TRACE=1 logs each body's start and sleep.
#include "bond/addr.h"
#include <algorithm>
#include <array>
#include <cmath>
#include <cstdlib>
#include <cstring>
#include <unordered_map>
#include <unordered_set>
#include <vector>

#include "common/auf.h"
#include "core/log.h"
#include "kernel/kernel.h"
#include "xdk/hle.h"

namespace {
constexpr uint32_t kDeadList = A(0x330400), kDeadCount = A(0x330404), kNameHashes = A(0x435220);
constexpr uint32_t kFrameSeconds = A(0x3B2420), kFrame = A(0x3B241C);
constexpr float kGravity = 515.0f;  // sv_gravity's default, units a second squared

struct V {
    float x = 0, y = 0, z = 0;
    V operator+(V o) const { return {x + o.x, y + o.y, z + o.z}; }
    V operator-(V o) const { return {x - o.x, y - o.y, z - o.z}; }
    V operator*(float k) const { return {x * k, y * k, z * k}; }
};
float Dot(V a, V b) { return a.x * b.x + a.y * b.y + a.z * b.z; }
V Cross(V a, V b) { return {a.y * b.z - a.z * b.y, a.z * b.x - a.x * b.z, a.x * b.y - a.y * b.x}; }
float Len(V a) { return std::sqrt(Dot(a, a)); }
V Norm(V a) {
    float l = Len(a);
    return l > 1e-6f ? a * (1 / l) : V{0, 0, 1};
}

struct Q {
    float x = 0, y = 0, z = 0, w = 1;
};
Q Mul(Q a, Q b) {
    return {a.w * b.x + a.x * b.w + a.y * b.z - a.z * b.y, a.w * b.y - a.x * b.z + a.y * b.w + a.z * b.x,
            a.w * b.z + a.x * b.y - a.y * b.x + a.z * b.w, a.w * b.w - a.x * b.x - a.y * b.y - a.z * b.z};
}
Q Conj(Q q) { return {-q.x, -q.y, -q.z, q.w}; }
V Rot(Q q, V v) {
    V u{q.x, q.y, q.z};
    V t = Cross(u, v) * 2;
    return v + t * q.w + Cross(u, t);
}
Q Normalize(Q q) {
    float l = std::sqrt(q.x * q.x + q.y * q.y + q.z * q.z + q.w * q.w);
    return l > 1e-6f ? Q{q.x / l, q.y / l, q.z / l, q.w / l} : Q{};
}
// the shortest turn taking direction a to b
Q Arc(V a, V b) {
    a = Norm(a), b = Norm(b);
    float d = Dot(a, b);
    if (d < -0.9999f) {  // opposite: about any perpendicular
        V p = std::abs(a.x) < 0.9f ? Cross(a, V{1, 0, 0}) : Cross(a, V{0, 1, 0});
        p = Norm(p);
        return {p.x, p.y, p.z, 0};
    }
    V c = Cross(a, b);
    return Normalize({c.x, c.y, c.z, 1 + d});
}
// the turn from an orthonormal frame (columns a, b, c) to another
Q FromFrame(V a, V b, V c) {
    float m00 = a.x, m10 = a.y, m20 = a.z, m01 = b.x, m11 = b.y, m21 = b.z, m02 = c.x, m12 = c.y, m22 = c.z;
    float tr = m00 + m11 + m22;
    Q q;
    if (tr > 0) {
        float s = std::sqrt(tr + 1) * 2;
        q = {(m21 - m12) / s, (m02 - m20) / s, (m10 - m01) / s, 0.25f * s};
    } else if (m00 > m11 && m00 > m22) {
        float s = std::sqrt(1 + m00 - m11 - m22) * 2;
        q = {0.25f * s, (m01 + m10) / s, (m02 + m20) / s, (m21 - m12) / s};
    } else if (m11 > m22) {
        float s = std::sqrt(1 + m11 - m00 - m22) * 2;
        q = {(m01 + m10) / s, 0.25f * s, (m12 + m21) / s, (m02 - m20) / s};
    } else {
        float s = std::sqrt(1 + m22 - m00 - m11) * 2;
        q = {(m02 + m20) / s, (m12 + m21) / s, 0.25f * s, (m10 - m01) / s};
    }
    return Normalize(q);
}

// the names' order at 0x2285A8
enum Name {
    kRoot, kHip, kRThigh, kRCalf, kRFoot, kRToe, kLThigh, kLCalf, kLFoot, kLToe, kLowTorso, kMidTorso, kUpTorso, kNeck,
    kHead, kRClavicle, kRBicep, kRForearm, kRHand, kLClavicle = 25, kLBicep, kLForearm, kLHand, kNames = 34
};
// the points, by name
constexpr Name kPoints[] = {kHip, kUpTorso, kHead, kRBicep, kRForearm, kRHand, kLBicep, kLForearm, kLHand,
                            kRThigh, kRCalf, kRFoot, kRToe, kLThigh, kLCalf, kLFoot, kLToe};
constexpr int kNPoints = int(std::size(kPoints));
constexpr int kTorso = 7;  // the first seven points move as one piece
// the limbs' bones: the bone (by name) aimed from its point at the next
struct Limb {
    Name bone, from, to;
};
constexpr Limb kLimbs[] = {{kRBicep, kRBicep, kRForearm}, {kRForearm, kRForearm, kRHand}, {kLBicep, kLBicep, kLForearm},
                           {kLForearm, kLForearm, kLHand},  {kRThigh, kRThigh, kRCalf},     {kRCalf, kRCalf, kRFoot},
                           {kRFoot, kRFoot, kRToe},         {kLThigh, kLThigh, kLCalf},     {kLCalf, kLCalf, kLFoot},
                           {kLFoot, kLFoot, kLToe}};
constexpr Name kTorsoBones[] = {kRoot, kHip, kLowTorso, kMidTorso, kUpTorso, kNeck, kHead, kRClavicle, kLClavicle};

struct Pose {
    V p;
    Q q;
};

Pose ReadPose(uint32_t at) {
    const float* f = reinterpret_cast<const float*>(&kernel::G<uint32_t>(at));
    return {{f[0], f[1], f[2]}, {f[4], f[5], f[6], f[7]}};
}
void WritePose(uint32_t at, const Pose& s) {
    float* f = reinterpret_cast<float*>(&kernel::G<uint32_t>(at));
    f[0] = s.p.x, f[1] = s.p.y, f[2] = s.p.z;
    f[4] = s.q.x, f[5] = s.q.y, f[6] = s.q.z, f[7] = s.q.w;
}

struct Skeleton {
    int bone[kNames];  // by name, -1 missing
    std::vector<int> parent;
    bool ok = false;
};

struct Body {
    uint32_t frame = 0;
    std::array<V, kNPoints> last{};  // the points the frame before (the living body's too: its motion carries on)
    bool has_last = false;
    bool limp = false, asleep = false;
    float age = 0, still = 0, floor = 0, seen_alive = 0;
    std::vector<Pose> kept;  // the pose at death
    std::array<V, kNPoints> p{}, prev{};
    std::array<float, kNPoints * kNPoints> rest{};
    std::vector<Pose> out;  // the pose drawn
    uint32_t mesh = 0;
};
std::unordered_map<uint32_t, Body> g_bodies;
std::unordered_map<uint32_t, Skeleton> g_skeletons;  // by mesh
uint32_t g_frame = ~0u;
std::unordered_set<uint32_t> g_dead;

bool Enabled() {
    static const int env = [] {
        const char* e = std::getenv("AUF_RAGDOLL");
        return e && *e ? (*e == '1' ? 1 : 0) : -1;
    }();
    return env >= 0 ? env == 1 : auf::ragdolls || std::getenv("AUF_RAGDOLL_TEST");
}
bool Test() {
    static const bool on = std::getenv("AUF_RAGDOLL_TEST") != nullptr;
    return on;
}
bool Trace() {
    static const bool on = std::getenv("AUF_RAGDOLL_TRACE") != nullptr;
    return on;
}

const Skeleton& SkeletonOf(uint32_t model) {
    const uint32_t mesh = kernel::R32(model + 0x10);
    auto [it, fresh] = g_skeletons.try_emplace(mesh);
    Skeleton& s = it->second;
    if (!fresh) return s;
    const uint32_t n = kernel::G<uint16_t>(model + 0x50), names = mesh ? kernel::R32(mesh + 0x74) : 0;
    const uint32_t parents = kernel::R32(model + 0x54);
    std::fill(std::begin(s.bone), std::end(s.bone), -1);
    if (!n || n > 256 || !names || !parents) return s;
    for (int k = 0; k < kNames; k++) {
        const uint32_t h = kernel::R32(kNameHashes + k * 4);
        if (!h) continue;
        for (uint32_t b = 0; b < n; b++)
            if (kernel::R32(names + b * 8 + 4) == h) {
                s.bone[k] = int(b);
                break;
            }
    }
    s.parent.resize(n);
    for (uint32_t b = 0; b < n; b++) s.parent[b] = int32_t(kernel::R32(parents + b * 8));
    s.ok = true;
    for (Name k : kPoints) s.ok &= s.bone[k] >= 0;
    for (const Limb& l : kLimbs) s.ok &= s.bone[l.bone] >= 0;
    if (Trace()) LOGR("ragdoll: mesh %08X, %u bones, %s", mesh, n, s.ok ? "a body" : "not a body");
    return s;
}

// the dead actors' models, once a frame
void Refresh() {
    const uint32_t frame = kernel::R32(kFrame);
    if (frame == g_frame) return;
    g_frame = frame;
    g_dead.clear();
    const uint32_t list = kernel::R32(kDeadList), n = std::min<uint32_t>(kernel::R32(kDeadCount), 256);
    for (uint32_t i = 0; list && i < n; i++) {
        const uint32_t e = kernel::R32(list + i * 4), edict = e ? kernel::R32(e + 0xC) : 0;
        const uint32_t model = edict && kernel::R32(edict + 0x108) ? kernel::R32(edict + 0x10C) : 0;
        if (model) g_dead.insert(model);
    }
    // bodies not drawn for a while are gone (removed, or another level)
    for (auto it = g_bodies.begin(); it != g_bodies.end();)
        it = frame - it->second.frame > 120 ? g_bodies.erase(it) : std::next(it);
}

void Start(Body& b, const Skeleton& s, uint32_t pose, uint32_t n) {
    b.limp = true, b.asleep = false, b.age = 0, b.still = 0;
    b.kept.resize(n);
    for (uint32_t i = 0; i < n; i++) b.kept[i] = ReadPose(pose + i * 0x20);
    b.floor = 1e9f;
    for (uint32_t i = 0; i < n; i++) b.floor = std::min(b.floor, b.kept[i].p.z);
    for (int i = 0; i < kNPoints; i++) {
        b.p[i] = b.kept[s.bone[kPoints[i]]].p;
        b.prev[i] = b.has_last ? b.last[i] : b.p[i];
    }
    for (int i = 0; i < kNPoints; i++)
        for (int j = 0; j < kNPoints; j++) b.rest[i * kNPoints + j] = Len(b.p[i] - b.p[j]);
    b.out = b.kept;
    if (Trace()) LOGR("ragdoll: %u bones go limp, floor %.1f", n, b.floor);
}

void Stick(Body& b, int i, int j, float stiff = 1.0f) {
    V d = b.p[j] - b.p[i];
    float l = Len(d), r = b.rest[i * kNPoints + j];
    if (l < 1e-5f) return;
    V c = d * (0.5f * stiff * (l - r) / l);
    b.p[i] = b.p[i] + c;
    b.p[j] = b.p[j] - c;
}

int PointOf(Name n) {
    for (int i = 0; i < kNPoints; i++)
        if (kPoints[i] == n) return i;
    return -1;
}

void Step(Body& b, float dt) {
    const float g = kGravity * dt * dt;
    float moved = 0;
    for (int i = 0; i < kNPoints; i++) {
        V v = (b.p[i] - b.prev[i]) * 0.99f;
        b.prev[i] = b.p[i];
        b.p[i] = b.p[i] + v + V{0, 0, -g};
    }
    for (int it = 0; it < 8; it++) {
        for (int i = 0; i < kTorso; i++)
            for (int j = i + 1; j < kTorso; j++) Stick(b, i, j);
        for (const Limb& l : kLimbs) Stick(b, PointOf(l.from), PointOf(l.to));
        // the hand and foot keep their distance to the torso a little (elbows and knees fold, not flat through it)
        for (Name a : {kRHand, kLHand, kRFoot, kLFoot}) Stick(b, PointOf(a), 0, 0.05f);
        for (int i = 0; i < kNPoints; i++)
            if (b.p[i].z < b.floor) {
                b.p[i].z = b.floor;
                V slide = b.p[i] - b.prev[i];
                b.prev[i].x = b.p[i].x - slide.x * 0.4f;  // friction on the ground
                b.prev[i].y = b.p[i].y - slide.y * 0.4f;
            }
    }
    for (int i = 0; i < kNPoints; i++) moved = std::max(moved, Len(b.p[i] - b.prev[i]));
    b.still = moved < 0.02f ? b.still + dt : 0;
    b.age += dt;
    if ((b.still > 0.6f && b.age > 1.0f) || b.age > 8.0f) {
        b.asleep = true;
        if (Trace()) LOGR("ragdoll: a body sleeps after %.1f s", b.age);
    }
}

// the torso's frame from its points: up the hips to the chest, across the hip joints
void Frame(const std::array<V, kNPoints>& p, V& a, V& bb, V& c) {
    a = Norm(p[1] - p[0]);
    V side = p[PointOf(kLThigh)] - p[PointOf(kRThigh)];
    c = Norm(Cross(a, side));
    bb = Cross(c, a);
}

void Drive(Body& b, const Skeleton& s) {
    const size_t n = b.kept.size();
    std::array<V, kNPoints> p0;
    for (int i = 0; i < kNPoints; i++) p0[i] = b.kept[s.bone[kPoints[i]]].p;
    V a0, b0, c0, a1, b1, c1;
    Frame(p0, a0, b0, c0);
    Frame(b.p, a1, b1, c1);
    const Q torso = Mul(FromFrame(a1, b1, c1), Conj(FromFrame(a0, b0, c0)));
    const V hip0 = p0[0], hip1 = b.p[0];
    std::vector<int> done(n, 0);  // 0 not yet, 1 placed
    auto place = [&](int bone, const Pose& to) {
        b.out[bone] = to;
        done[bone] = 1;
    };
    for (Name k : kTorsoBones)
        if (int bone = s.bone[k]; bone >= 0) {
            const Pose& was = b.kept[bone];
            place(bone, {hip1 + Rot(torso, was.p - hip0), Normalize(Mul(torso, was.q))});
        }
    for (const Limb& l : kLimbs) {
        const int bone = s.bone[l.bone], i = PointOf(l.from), j = PointOf(l.to);
        const Pose& was = b.kept[bone];
        const Q turn = Mul(Arc(Rot(torso, p0[j] - p0[i]), b.p[j] - b.p[i]), torso);
        place(bone, {b.p[i], Normalize(Mul(turn, was.q))});
    }
    // the rest with their parents, parents first
    for (int pass = 0; pass < 16; pass++) {
        bool left = false;
        for (size_t bone = 0; bone < n; bone++) {
            if (done[bone]) continue;
            const int par = s.parent[bone];
            if (par < 0 || par >= int(n)) {
                place(int(bone), b.kept[bone]);
                continue;
            }
            if (!done[par]) {
                left = true;
                continue;
            }
            const Q d = Mul(b.out[par].q, Conj(b.kept[par].q));
            place(int(bone), {b.out[par].p + Rot(d, b.kept[bone].p - b.kept[par].p), Normalize(Mul(d, b.kept[bone].q))});
        }
        if (!left) break;
    }
}
}  // namespace

X86_EXTERN_FUNC(__imp__sub_00146C70);
X86_FUNC(sub_00146C70) {
    const uint32_t model = ctx.ecx;
    if (!Enabled() || !model) return __imp__sub_00146C70(ctx, base);
    Refresh();
    const uint32_t pose = kernel::R32(model + 0x5C), n = kernel::G<uint16_t>(model + 0x50);
    if (!pose || !n || n > 256) return __imp__sub_00146C70(ctx, base);
    const Skeleton& s = SkeletonOf(model);
    if (!s.ok || s.parent.size() != n) return __imp__sub_00146C70(ctx, base);
    Body& b = g_bodies[model];
    const uint32_t frame = kernel::R32(kFrame);
    const bool new_frame = frame != b.frame;
    b.frame = frame;
    const float dt = std::clamp(*reinterpret_cast<const float*>(&kernel::G<uint32_t>(kFrameSeconds)), 0.0f, 0.05f);
    bool dead = g_dead.count(model) != 0;
    if (Test()) {  // every character, 2 s after it is first drawn
        if (new_frame) b.seen_alive += dt;
        dead = b.seen_alive > 2.0f;
    }
    if (!dead) {
        if (b.limp) b = Body{}, b.frame = frame;  // the same model alive again (reused)
        if (new_frame) {
            for (int i = 0; i < kNPoints; i++) b.last[i] = ReadPose(pose + s.bone[kPoints[i]] * 0x20).p;
            b.has_last = true;
        }
        return __imp__sub_00146C70(ctx, base);
    }
    if (!b.limp || b.kept.size() != n) Start(b, s, pose, n);
    if (new_frame && !b.asleep && !auf::MenuUp() && dt > 0) {
        Step(b, dt);
        Drive(b, s);
    }
    // the ragdoll's pose for the skinning only, the game's back after it
    std::vector<uint8_t> game(n * 0x20);
    std::memcpy(game.data(), &kernel::G<uint8_t>(pose), game.size());
    for (uint32_t i = 0; i < n; i++) WritePose(pose + i * 0x20, b.out[i]);
    kernel::G<uint32_t>(model + 0x2B4) = 0;  // the skin's frame guard: made again from this pose
    __imp__sub_00146C70(ctx, base);
    std::memcpy(&kernel::G<uint8_t>(pose), game.data(), game.size());
}
